"""Retain numeric data and selected raw instruction bytes without running the target."""
import hashlib,json,math,re
from pathlib import Path
from pe import PE
root=Path('investigation/native/small-parts');p=PE('stormworks64.exe')
sha=hashlib.sha256(p.data).hexdigest();assert sha=='f9206d85c82f4d02fd0ac391781d19c5c68394a9ffc48accca0e1f5966db8699'
constants={}
for a in [0x140baf8a0,0x140baf8c4,0x140baf8f8,0x140bafa00,0x140bafad0,0x140baf958,0x140baf98c,0x140bafcbc,0x140bafe18,0x140bafecc,0x140bb064c,0x140bb0860,0x140bb0864,0x140bb0874,0x140bb07f8]:constants[hex(a)]={'file_offset':hex(p.offset(a)),'bytes':p.read(a,4).hex(' '),'float32':p.value(a,'f')}
anchors={}
for f in (root/'asm').glob('*.asm'):
 for l in f.read_text().splitlines():
  m=re.match(r'\s*([0-9a-f]+):\s+((?:[0-9a-f]{2} )*[0-9a-f]{2})\s+(.+)',l)
  if m and int(m[1],16) in [0x1403f2c1b,0x1403f2c35,0x1403f2cb3,0x1403f2b1c,0x1403f4f51,0x1403f4f56,0x1403c9a5f,0x1403c9c96,0x1403c9c9e,0x140396c1d,0x140357a84,0x140357a8a,0x1403564a6,0x140396a93,0x140396ac3,0x140396aeb,0x140396af3]:anchors['0x'+m[1]]={'bytes':m[2],'instruction':m[3]}
bindings={}
for name,vt,slots in [('water',0x140b08f18,[0x358,0x498]),('inventory',0x140b655d8,[0x358]),('multibody',0x140b02a08,[0x358]),('script_operators',0x140b11a28,[0x2f8,0x3d8,0x3e0])]:
 bindings[name]={'vtable':hex(vt),'slots':{hex(z):{'address':hex(vt+z),'bytes':p.read(vt+z,8).hex(' '),'target':hex(p.value(vt+z,'Q'))} for z in slots}}
dispatch={str(n):{'address':hex(0x1403f5100+4*n),'bytes':p.read(0x1403f5100+4*n,4).hex(' '),'target':hex(p.base+p.value(0x1403f5100+4*n,'I'))} for n in [33,34]}
(root/'tools/byte-evidence.json').write_text(json.dumps({'target_sha256':sha,'constants':constants,'instructions':anchors,'bindings':bindings,'water_dispatch':dispatch},indent=2)+'\n')
items=json.loads((root/'tools/item-table.json').read_text());gas=[1,3,79,80,149]
electric=[dict(x,charge_request_per_update=.01,charge_request_per_simulated_second=.6,recharge_percent_per_update=100/x['recharge_seconds']/60,nominal_full_recharge_cost=.6*x['recharge_seconds']) for x in items if (x['capacity'] or 0)>0 and (x['recharge_seconds'] or 0)>0 and x['id'] not in gas]
rows=[]
for n in ['inventory_small','inventory_medium']:rows.append({'definition':n,'issue':28,'status':'decoded','request_per_update':.01,'request_per_simulated_second':.6,'electric_items':electric,'gas_refill_ids':gas,'routine':'0x140396950','example':{'item':'inventory_equipment_flashlight','seconds_from_empty':1500,'total_internal_charge':900}})
rows.append({'definition':'cryo_cooler','issue':51,'status':'decoded_in_internal_units','water_component_type':33,'routine':'0x1403f4d1e..0x1403f509d','electric_request_per_update':.001,'electric_request_per_simulated_second':.06,'minimum_draw_fraction_exclusive':.1,'q_per_liquid_litre':{n:.1 for n in ['fresh_water','diesel','jet_fuel','oil','seawater','slurry','saturated_slurry']},'temperature_change_per_update':{'A':'-0.03*qB/(qA+qB)','B':'+0.03*qA/(qA+qB)'},'mutual_heat_amount_C_per_update':'0.03*qA*qB/(qA+qB)','threshold':'qA+qB > float32(0.001)','ambient_relaxation_after_mutual':.001,'example':{'liquid_litres_A':1,'liquid_litres_B':1,'qA':.1,'qB':.1,'delta_A_C_per_update':-.015,'delta_B_C_per_update':.015,'mutual_heat_litre_C_per_update':.015},'open':['SI joule/watt conversion remains unestablished']})
rows.append({'definition':'hydrogen_fuel_cell','issue':56,'status':'decoded','water_component_type':34,'routine':'0x1403ef860 case 34 at 0x1403f2b03','oxygen_amount_per_update':.000165,'hydrogen_amount_per_update':.00033,'water_amount_per_update':.03,'electric_charge_per_update':1,'oxygen_expanded_L_per_second':5.94,'hydrogen_expanded_L_per_second':11.88,'water_L_per_second':18,'electric_charge_per_second':60,'example':{'active_updates':600,'oxygen_expanded_L':59.4,'hydrogen_expanded_L':118.8,'water_L':180,'electric_charge':600},'conditions':['undamaged','oxygen and hydrogen packet available','water free capacity >= 0.03 amount'],'open':['SI electrical conversion','runtime throughput under connected port pressure']})
c=constants['0x140bafe18']['float32'];rows.append({'definition':'laser_point_sensor','issue':58,'status':'decoded','logic_gate_type':48,'routine':'0x1403c9670','forward_dot_minimum_exclusive':.5,'full_cone_degrees':120,'output_formula':'direction dot sensor_right_or_up / float32(cos(0.5 radians))','denominator':c,'units':'dimensionless direction projection','open_cone_axis_output_bound':math.sqrt(.75)/c,'example':{'angle_from_forward_degrees':30,'horizontal_output':.5/c,'vertical_output':0},'open':['runtime validation was not performed']})
rows.append({'definition':'oil_rig_pumpjack_b','issue':89,'status':'mechanical_child_and_zero_independent_output_decoded','definition_type':7,'oil_component_type':6,'mass':500,'constraint_type':1,'constraint_axis':1,'logic_ports':0,'parent_definition':'oil_rig_pumpjack','parent_child_name':'oil_rig_pumpjack_b','own_fluid_outlet':False,'own_oil_amount_per_update':0,'own_oil_amount_per_second':0,'routine':'0x140357a60','fluid_update_skipped_by_flag':128,'example':'The parent definition names this piston as its child and carries Fluid Out; B has no Fluid Out.','open':['complete parent oil production law and B travel-to-pumped-volume relation']})
rows.append({'definition':'default_resource_storage','issue':152,'status':'callback_amounts_decoded_native_conservation_open','resource':'rom/data/missions/default_resource_storage/script.lua','port_update_every_callbacks':60,'inlet':'add tank_data.values[1 or 2], then queue clear fluid 0 and nitrogen','outlet_delta':'max(0,min(capacity-total_value,tile_stock))','outlet_assignment':'set old total+delta of old dominant fluid_type, then clear nitrogen','example':{'capacity':100,'old_total':40,'tile_stock':25,'delta':25,'new_requested_total':65,'new_tile_stock':0},'native_set_named':'0x140730ea0','native_enqueue':'0x140730f50','native_get_named':'0x140733a30','open':['wall-clock callback cadence','native queued write application, clamping, and ordering','mixed-fluid conservation and failure handling']})
(root/'parts.json').write_text(json.dumps({'target_sha256':sha,'timing':'60 updates per nominal active simulated second, not a wall-clock promise','parts':rows},indent=2)+'\n')
print('Wrote parts.json and byte-evidence.json; electric item IDs:',','.join(str(x['id']) for x in electric))
